// AccessLogListener.java
package com.demo;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.Date;
import javax.servlet.*;
import javax.servlet.annotation.WebListener;
import javax.servlet.http.HttpServletRequest;
@WebListener
public class AccessLogListener
    implements ServletRequestListener {
  public void requestInitialized(
      ServletRequestEvent e) {
    HttpServletRequest r =
        (HttpServletRequest) e.getServletRequest();
    String time = new SimpleDateFormat(
        "yyyy-MM-dd HH:mm:ss").format(new Date());
    String line = time + " " + r.getRemoteAddr()
        + " " + r.getRequestURI();
    String path = e.getServletContext()
        .getRealPath("/WEB-INF/access.log");
    synchronized (AccessLogListener.class) {
      try (PrintWriter pw = new PrintWriter(
          new OutputStreamWriter(
              new FileOutputStream(path, true),
              "UTF-8"))) {
        pw.println(line);
      } catch (IOException ex) {
        e.getServletContext().log("写日志失败", ex);
      }
    }
  }
  public void requestDestroyed(
      ServletRequestEvent e) { }
}

// CounterListener.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.annotation.WebListener;
@WebListener
public class CounterListener
    implements ServletContextListener {
  private String path(ServletContextEvent e) {
    return e.getServletContext()
        .getRealPath("/WEB-INF/count.txt");
  }
  public void contextInitialized(
      ServletContextEvent e) {
    int n = 0;
    try (BufferedReader br = new BufferedReader(
        new FileReader(path(e)))) {
      n = Integer.parseInt(br.readLine().trim());
    } catch (Exception ex) { }
    e.getServletContext().setAttribute("count", n);
  }
  public void contextDestroyed(
      ServletContextEvent e) {
    Object n = e.getServletContext()
        .getAttribute("count");
    try (PrintWriter pw = new PrintWriter(
        new FileWriter(path(e)))) {
      pw.println(n);
    } catch (IOException ex) { }
  }
}
